package app.trace.telemetry

import java.math.BigDecimal
import java.math.RoundingMode

/**
 * replay3d.py (HTML export only; the GIF export is desktop-only): a single self-contained offline HTML page that
 * draws the racing line from the lap's world position, coloured by speed, with a moving car, an optional ghost lap
 * and a synced trace. The page template is the desktop's `replay3d._PAGE`, shipped as assets/replay3d.html
 * (generated by tools/gen_android_webui.py) so the phone writes the very same file the PC does.
 */
object ReplayHtml {
    const val MAX_POINTS = 1500

    private fun num(v: Double) = if (v.isFinite()) v else 0.0
    /** Python round(): exact binary value, half to even, and a negative value that rounds to zero stays -0.0. */
    private fun r(x: Double, nd: Int): Double {
        val v = BigDecimal(x).setScale(nd, RoundingMode.HALF_EVEN).toDouble()
        return if (v == 0.0 && (x < 0 || (x == 0.0 && 1.0 / x < 0))) -0.0 else v
    }

    /** [x, y(up), z, speed, throttle, brake, t] per sample, thinned to MAX_POINTS (replay3d._compact). */
    fun compact(df: Frame?): List<DoubleArray> {
        if (df == null || df.compact || !df.has("world_x")) return emptyList()
        fun c(name: String) = if (df.has(name)) df[name] else DoubleArray(df.n)
        val x = c("world_x"); val y = c("world_y"); val z = c("world_z"); val s = c("speed_kmh"); val th = c("throttle"); val b = c("brake"); val t = c("t")
        var rows = List(df.n) { doubleArrayOf(num(x[it]), num(y[it]), num(z[it]), num(s[it]), num(th[it]), num(b[it]), num(t[it])) }
        if (rows.size > MAX_POINTS) {
            val step = rows.size.toDouble() / MAX_POINTS
            rows = List(MAX_POINTS) { rows[(it * step).toInt()] }
        }
        if (rows.isNotEmpty()) {
            val t0 = rows[0][6]
            for (row in rows) {
                row[6] = r(row[6] - t0, 3)
                for (i in 0 until 6) row[i] = r(row[i], 2)
            }
        }
        return rows
    }

    fun usable(df: Frame?) = compact(df).size >= 20

    /** json.dumps float formatting: repr() with a trailing .0 on whole numbers, no exponent for the magnitudes used here. */
    private fun py(d: Double): String {
        if (d == 0.0 && 1.0 / d < 0) return "-0.0"
        if (d == Math.rint(d) && Math.abs(d) < 1e15) return d.toLong().toString() + ".0"
        return BigDecimal(d.toString()).toPlainString()
    }

    private fun json(rows: List<DoubleArray>) = rows.joinToString(",", "[", "]") { row -> row.joinToString(",", "[", "]") { py(it) } }

    fun build(lap: Frame, title: String = "TRACE lap replay", ghost: Frame? = null, template: String): String {
        val blob = "{\"lap\":${json(compact(lap))},\"ghost\":${if (ghost != null) json(compact(ghost)) else "[]"}}".replace("</", "<\\/")
        val safeTitle = (if (title.isEmpty()) "TRACE lap replay" else title).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        return template.replace("/*@TITLE@*/", safeTitle).replace("/*@DATA@*/", blob)
    }
}
